window.CARDS=window.CARDS||{};CARDS["people-tsubaki-sakurako"]=[{"i":"sc-tsubaki-sakurako-y2v1-p268-1","v":"y2v1","y":2,"o":16,"k":"","w":"utomiya-riku ayanokouji-kiyotaka tsubaki-sakurako","q":"tsubaki sakurako ch 5  seeking a partner approaches ayanokoji at keyaki mall with utomiya  explains she hasn t found a partner yet  leaves to search elsewhere  searches with him  approaches him","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v1-p268-1\"><h3><span class=\"ttl\">Ch.5: Seeking a partner<\/span><span class=\"meta\">Y2V1 · p.268–275<\/span><\/h3><p class=\"setup\">Approaches Ayanokōji at Keyaki Mall with Utomiya. Explains she hasn’t found a partner yet. Leaves to search elsewhere.<\/p><p class=\"with\">with <a href=\"utomiya-riku.html\">Utomiya Riku<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> Searches with him.<span class=\"pg\">p.268–275<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Approaches him.<span class=\"pg\">p.268–275<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v1-p268-2\">→ After: Epilogue: Seeking a partner<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v1-p268-2","v":"y2v1","y":2,"o":16,"k":"","w":"utomiya-riku ayanokouji-kiyotaka tsubaki-sakurako","q":"tsubaki sakurako epilogue  seeking a partner approaches ayanokoji at keyaki mall  leaves to search elsewhere  searches with him  approaches him","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v1-p268-2\"><h3><span class=\"ttl\">Epilogue: Seeking a partner<\/span><span class=\"meta\">Y2V1 · p.268–275<\/span><\/h3><p class=\"setup\">Approaches Ayanokōji at Keyaki Mall. Leaves to search elsewhere.<\/p><p class=\"with\">with <a href=\"utomiya-riku.html\">Utomiya Riku<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> Searches with him.<span class=\"pg\">p.268–275<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Approaches him.<span class=\"pg\">p.268–275<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v1-p268-1\">← Before: Ch.5: Seeking a partner<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v1-p268-3\">→ After: Tsubaki and Utomiya approach Ayanokōji about partnering<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v1-p268-3","v":"y2v1","y":2,"o":16,"k":"narration spoken","w":"utomiya-riku ayanokouji-kiyotaka tsubaki-sakurako","q":"tsubaki sakurako tsubaki and utomiya approach ayanokoji about partnering on the walk back from keyaki mall  she and utomiya riku  class 1 c  call out to ayanokoji  she repeatedly checks her phone  the oaa app   i m utomiya  and her name is tsubaki  could we talk with you for a bit about becoming partners for this special exam   we re currently going around searching for upperclassmen with academic ability ratings of a c or higher who are willing to cooperate with us   you re class 2 d s  ayanokoji senpai  correct    tsubaki a class 1 c first year with a c  academic rating  still unpaired  she and utomiya seek a c or higher upperclassman  and propose moving to a cafe to discuss   a timing that strikes ayanokoji as  far too good to be true  her classmate  he spearheads the conversation and already has a partner  approaches him about partnering  he is wary the encounter was arranged","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v1-p268-3\"><h3><span class=\"ttl\">Tsubaki and Utomiya approach Ayanokōji about partnering<\/span><span class=\"meta\">Y2V1 · p.268–271<\/span><\/h3><p class=\"setup\">On the walk back from Keyaki Mall, she and Utomiya Riku (Class 1-C) call out to Ayanokōji; she repeatedly checks her phone (the OAA app).<\/p><p class=\"with\">with <a href=\"utomiya-riku.html\">Utomiya Riku<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Utomiya Riku<\/b> &quot;I&#x27;m Utomiya, and her name is Tsubaki. Could we talk with you for a bit about becoming partners for this special exam?&quot;<span class=\"pg\">p.270<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Utomiya Riku<\/b> &quot;We&#x27;re currently going around searching for upperclassmen with Academic Ability ratings of a C or higher who are willing to cooperate with us.&quot;<span class=\"pg\">p.270<\/span><\/li><li class=\"q narration\">&quot;You&#x27;re Class 2-D&#x27;s… Ayanokōji-senpai, correct?&quot; — Tsubaki<span class=\"pg\">p.270<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> A Class 1-C first-year with a C− Academic rating, still unpaired; she and Utomiya seek a C-or-higher upperclassman, and propose moving to a café to discuss — a timing that strikes Ayanokōji as &quot;far too good to be true.&quot;<span class=\"pg\">p.268–271<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> Her classmate; he spearheads the conversation and already has a partner.<span class=\"pg\">p.268–271<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Approaches him about partnering; he is wary the encounter was arranged.<span class=\"pg\">p.268–271<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v1-p268-2\">← Before: Epilogue: Seeking a partner<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v2-p258-1","v":"y2v2","y":2,"o":17,"k":"","w":"tsubaki-sakurako","q":"tsubaki sakurako tsubaki at the cafe she stations herself behind yagami with a good view of ayanokoji and the group  she takes out her phone  she is either following ayanokoji or yagami  both contacts now revealed","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v2-p258-1\"><h3><span class=\"ttl\">Tsubaki at the café<\/span><span class=\"meta\">Y2V2 · p.258<\/span><\/h3><p class=\"setup\">She stations herself behind Yagami with a good view of Ayanokōji and the group; she takes out her phone.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> She is either following Ayanokōji or Yagami; both contacts now revealed.<span class=\"pg\">p.258<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v2-p264-1\">→ After: The Hōsen plan at the convenience store<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v2-p264-1","v":"y2v2","y":2,"o":17,"k":"spoken","w":"ayanokouji-kiyotaka utomiya-riku yagami-takuya tsubaki-sakurako","q":"tsubaki sakurako the hosen plan at the convenience store she grabs a lollipop as cover and calls for utomiya outside the store   umm   i d like to talk to you about something  could you wait outside for me   sorry to keep you waiting   there is something that we wanted to tell you  that s why i approached you   is it utomiya   looks like i was right   i guess i know the reason now  but what does it have to do with me   didn t you get that injury on your left hand after you fought with housen   because we were also aiming for the 20 million point bounty  she keeps the conversation short and the meeting friendly  she does not reveal yagami s disclosure to him  and he does not reveal hers  she wants him on board against housen  her classmate  she helps him talk him into it  she observed his cafe meet with ayanokoji","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v2-p264-1\"><h3><span class=\"ttl\">The Hōsen plan at the convenience store<\/span><span class=\"meta\">Y2V2 · p.264–270<\/span><\/h3><p class=\"setup\">She grabs a lollipop as cover and calls for Utomiya outside the store.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"utomiya-riku.html\">Utomiya Riku<\/a> · <a href=\"yagami-takuya.html\">Yagami Takuya<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Umm…”<span class=\"pg\">p.264<\/span><\/li><li class=\"q spoken\">“I’d like to talk to you about something. Could you wait outside for me?”<span class=\"pg\">p.264<\/span><\/li><li class=\"q spoken\">“Sorry to keep you waiting.”<span class=\"pg\">p.265<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “There is something that we wanted to tell you, that’s why I approached you.”<span class=\"pg\">p.266<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Is it Utomiya?”<span class=\"pg\">p.266<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Looks like I was right.”<span class=\"pg\">p.266<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I guess I know the reason now, but what does it have to do with me?”<span class=\"pg\">p.267<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Didn’t you get that injury on your left hand after you fought with Housen?”<span class=\"pg\">p.269<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Because we were also aiming for the 20 million point bounty.”<span class=\"pg\">p.269<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> She keeps the conversation short and the meeting friendly; she does not reveal Yagami&#x27;s disclosure to him, and he does not reveal hers.<span class=\"pg\">p.268–270<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She wants him on board against Housen.<span class=\"pg\">p.264–270<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> Her classmate; she helps him talk him into it.<span class=\"pg\">p.264–270<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yagami Takuya<\/b> She observed his café meet with Ayanokōji.<span class=\"pg\">p.258<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v2-p258-1\">← Before: Tsubaki at the café<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v2-p351-1\">→ After: SS: What Could Be Seen From That Back (Tsubaki POV)<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v2-p351-1","v":"y2v2","y":2,"o":17,"k":"narration","w":"utomiya-riku ayanokouji-kiyotaka tsubaki-sakurako","q":"tsubaki sakurako ss  what could be seen from that back  tsubaki pov  she tails him to the convenience store  she grabs a lollipop as cover  she calls for utomiya   if i was asked about what i was best at  i would without hesitation say it was my insight and intuition   on the way back to the dorms from the keyaki mall   but  he had definitely noticed me   i had been silently trailing him until now  but he hadn t shown any signs of having noticed me   but  he had definitely noticed me   there s something i want to speak to you about  so could you wait outside for a moment   buying at least a lollipop was the least i could do to show courtesy towards the shop and not just window shopping   thanks for waiting for me   so what did you want to talk about   there was something he had to tell you if i happen to meet you now ayanokouji senpai   utoumiya kun did   guess i was right   he said he would head over here  at once  her interior monologue  she s the lollipop holder who isn t good at conversation  she buys time for utomiya  she doesn t yet understand what he s planning  the friend she is stalling for  the prey she s learned to read","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v2-p351-1\"><h3><span class=\"ttl\">SS: What Could Be Seen From That Back (Tsubaki POV)<\/span><span class=\"meta\">Y2V2 · p.351–353<\/span><\/h3><p class=\"setup\">She tails him to the convenience store; she grabs a lollipop as cover; she calls for Utomiya.<\/p><p class=\"with\">with <a href=\"utomiya-riku.html\">Utomiya Riku<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q narration\">“If I was asked about what I was best at, I would without hesitation say it was my insight and intuition.”<span class=\"pg\">p.351<\/span><\/li><li class=\"q narration\">“On the way back to the dorms from the Keyaki mall.”<span class=\"pg\">p.351<\/span><\/li><li class=\"q narration\">“But, he had definitely noticed me.”<span class=\"pg\">p.351<\/span><\/li><\/ul><details class=\"more\"><summary>13 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> “I had been silently trailing him until now, but he hadn’t shown any signs of having noticed me.”<span class=\"pg\">p.351<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “But, he had definitely noticed me.”<span class=\"pg\">p.351<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “There’s something I want to speak to you about, so could you wait outside for a moment?”<span class=\"pg\">p.352<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “Buying at least a lollipop was the least I could do to show courtesy towards the shop and not just window shopping.”<span class=\"pg\">p.352<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “Thanks for waiting for me.”<span class=\"pg\">p.352<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “So what did you want to talk about?”<span class=\"pg\">p.352<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “There was something he had to tell you if I happen to meet you now Ayanokouji-senpai.”<span class=\"pg\">p.352<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “Utoumiya-kun did?”<span class=\"pg\">p.352<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “Guess I was right.”<span class=\"pg\">p.353<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “He said he would head over here, at once.”<span class=\"pg\">p.353<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Her interior monologue; she&#x27;s the lollipop-holder who isn&#x27;t good at conversation; she buys time for Utomiya; she doesn&#x27;t yet understand what he&#x27;s planning.<span class=\"pg\">p.351–353<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> The friend she is stalling for.<span class=\"pg\">p.351–353<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> The prey she&#x27;s learned to read.<span class=\"pg\">p.351–353<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v2-p264-1\">← Before: The Hōsen plan at the convenience store<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v3-p192-1","v":"y2v3","y":2,"o":18,"k":"","w":"tsubaki-sakurako","q":"tsubaki sakurako tsubaki at the slope tsubaki sakurako of class 1 c  present with the first year group  perfectly calm  undeterred  watches everything  the group composition matches shinohara s description of the group passing them after 8 30 pm last night  three girls and one boy  the girls 1 a 1 b 1 c  the boy 1 d  the match is an observation  not a conclusion   the identity of the perpetrator is not printed on these pages","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v3-p192-1\"><h3><span class=\"ttl\">Tsubaki at the slope<\/span><span class=\"meta\">Y2V3 · p.192–193<\/span><\/h3><p class=\"setup\">Tsubaki Sakurako of Class 1-C; present with the first-year group; perfectly calm; undeterred; watches everything.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> The group composition matches Shinohara&#x27;s description of the group passing them after 8:30 PM last night (three girls and one boy; the girls 1-A/1-B/1-C, the boy 1-D). The match is an observation, not a conclusion — the identity of the perpetrator is not printed on these pages.<span class=\"pg\">p.192–193<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v3-p267-1\">→ After: Tsubaki: the minds behind the bonfire<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v3-p267-1","v":"y2v3","y":2,"o":18,"k":"spoken","w":"utomiya-riku yagami-takuya housen-kazuomi kushida-kikyou tsubaki-sakurako","q":"tsubaki sakurako tsubaki  the minds behind the bonfire class c s tsubaki  scary quiet  orchestrated the first years  meeting under a bonfire  probes yagami with her thousand yard stare  the kushida hook  utomiya does the hands for her   well  he doesn t really seem the type to show up on time  or maybe he s just not coming   what   what do you mean   your oaa ratings are  at a glance  below average  in fact  there doesn t seem to be anything remarkable about you in the slightest  however  from what i ve seen during the battles we first years have taken part in so far  you ve been one to provide fairly critical insight from time to time  furthermore   hmmm  you say some interesting stuff  yagami kun  so the reason you supported my proposal to set this up is cuz you knew i thought of something   well  yagami kun  how  bout i tell you something interesting   though  do know that after you hear it  i won t be able to guarantee anything   yagami kun  you said just now that utomiya kun and i ve been scheming from the shadows to try n get ayanokoji senpai kicked outta school  yeah   a reward of 20 million private points  just for getting a senpai expelled  just about anybody would find that attractive  yeah   not for you  sorry  but i m having a hard time believing that  you make yourself seem harmless  but aren t you really lookin  to get ayanokoji senpai expelled as well  hell  you might even be more obsessed with it than hosen kun and amasawa san   it s the kinda thing i can tell just by looking at you  i ll have you know that i ve gotta lotta confidence in my eye for people   it s hard to imagine given the way you normally act  but like  i d imagine that your plan started out with pretending to be an ally so you could slowly get closer to him and stab  em right in the back  or am i wrong   you    speaker untagged in the print  recorded unassigned   well whatever  we ll get back to that later  getting back to the point  the situation s currently looking kinda cruddy  wouldn t you say   apparently  nanase san s been sticking together with ayanokoji senpai for a while now  i heard that he s even given her permission to tag along too  i tried checking up on them with the gps search feature just to make sure  and sure enough  the both of  em are up in area c3 together right now   i m saying that we gotta take action sooner rather than later  if hosen kun gets ayanokoji senpai expelled  it ll all be over for the rest of us  if possible  i d like to hear what kinda plans you ve thought of to get senpai kicked out  just as a reference  you get me   if you don t willingly cooperate starting now  you might end up paying dearly later   well  like  someone important to you ll be in danger  or something like that   ah  what s that about kushida senpai  do tell   yagami kun  i get that you think kushida senpai is like  the key to getting ayanokoji senpai expelled  but why is that  how exactly do you plan on making use of her  the coldest running mind in class c  never raises her voice  pulls strings with information  not force  her eye never falters  her quiet accomplice  the target of the probe  the absent exec whose delay she planned around  the named lever for yagami","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v3-p267-1\"><h3><span class=\"ttl\">Tsubaki: the minds behind the bonfire<\/span><span class=\"meta\">Y2V3 · p.267–274<\/span><\/h3><p class=\"setup\">Class C&#x27;s Tsubaki; scary-quiet; orchestrated the first-years&#x27; meeting under a bonfire; probes Yagami with her thousand-yard stare; the Kushida hook; Utomiya does the hands for her.<\/p><p class=\"with\">with <a href=\"utomiya-riku.html\">Utomiya Riku<\/a> · <a href=\"yagami-takuya.html\">Yagami Takuya<\/a> · <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Well, he doesn’t really seem the type to show up on time. Or maybe he’s just not coming.”<span class=\"pg\">p.268<\/span><\/li><li class=\"q spoken\">“What…?”<span class=\"pg\">p.269<\/span><\/li><li class=\"q spoken\">“What do you mean?”<span class=\"pg\">p.269<\/span><\/li><\/ul><details class=\"more\"><summary>22 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Your OAA ratings are, at a glance, below average. In fact, there doesn’t seem to be anything remarkable about you in the slightest. However, from what I’ve seen during the battles we first-years have taken part in so far, you’ve been one to provide fairly critical insight from time to time. Furthermore…”<span class=\"pg\">p.269<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hmmm. You say some interesting stuff, Yagami-kun. So the reason you supported my proposal to set this up is cuz you knew I thought of something?”<span class=\"pg\">p.269<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, Yagami-kun, how ‘bout I tell you something interesting?”<span class=\"pg\">p.269<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Though, do know that after you hear it… I won’t be able to guarantee anything.”<span class=\"pg\">p.270<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yagami-kun, you said just now that Utomiya-kun and I’ve been scheming from the shadows to try’n get Ayanokōji-senpai kicked outta school, yeah?”<span class=\"pg\">p.270<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “A reward of 20 million private points, just for getting a senpai expelled? Just about anybody would find that attractive, yeah?”<span class=\"pg\">p.270<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Not for you? Sorry, but I’m having a hard time believing that. You make yourself seem harmless, but aren’t you really lookin’ to get Ayanokōji-senpai expelled as well? Hell, you might even be more obsessed with it than Hōsen-kun and Amasawa-san.”<span class=\"pg\">p.270<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s the kinda thing I can tell just by looking at you. I’ll have you know that I’ve gotta lotta confidence in my eye for people.”<span class=\"pg\">p.270<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s hard to imagine given the way you normally act, but like… I’d imagine that your plan started out with pretending to be an ally so you could slowly get closer to him and stab ‘em right in the back. Or am I wrong?”<span class=\"pg\">p.270<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “You…” — speaker untagged in the print; recorded unassigned.<span class=\"pg\">p.271<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well whatever, we’ll get back to that later. Getting back to the point, the situation’s currently looking kinda cruddy, wouldn’t you say?”<span class=\"pg\">p.271<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Apparently, Nanase-san’s been sticking together with Ayanokōji-senpai for a while now. I heard that he’s even given her permission to tag along too. I tried checking up on them with the GPS Search feature just to make sure, and sure enough, the both of ‘em are up in area C3 together right now.”<span class=\"pg\">p.271<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m saying that we gotta take action sooner rather than later. If Hōsen-kun gets Ayanokōji-senpai expelled, it’ll all be over for the rest of us. If possible, I’d like to hear what kinda plans you’ve thought of to get Senpai kicked out, just as a reference. You get me?”<span class=\"pg\">p.271<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If you don’t willingly cooperate starting now, you might end up paying dearly later.”<span class=\"pg\">p.271<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, like, someone important to you’ll be in danger, or something like that.”<span class=\"pg\">p.271<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ah, what’s that about Kushida-senpai? Do tell.”<span class=\"pg\">p.271<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yagami-kun, I get that you think Kushida-senpai is like, the key to getting Ayanokōji-senpai expelled, but why is that? How exactly do you plan on making use of her?”<span class=\"pg\">p.272<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> The coldest-running mind in Class C; never raises her voice; pulls strings with information, not force; her eye never falters.<span class=\"pg\">p.267–274<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> Her quiet accomplice.<span class=\"pg\">p.267–274<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yagami Takuya<\/b> The target of the probe.<span class=\"pg\">p.267–274<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> The absent exec whose delay she planned around.<span class=\"pg\">p.267–274<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> The named lever for Yagami.<span class=\"pg\">p.267–274<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v3-p192-1\">← Before: Tsubaki at the slope<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v3-p322-1\">→ After: Tsubaki named at the walkie-talkie debrief<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v3-p322-1","v":"y2v3","y":2,"o":18,"k":"","w":"tsubaki-sakurako","q":"tsubaki sakurako tsubaki named at the walkie talkie debrief  tsubaki san and the others had been more informed than i anticipated  it was a surprise for me too    named by yagami  not present  pov switch to kushida   if you don t willingly cooperate starting now  you might end up paying dearly later    tsubaki s earlier line retold in his account  not present  same scene   there s a chance tsubaki san is conspiring something too  she might try and pull something at the same time as us  so i ll be poking around to try and find out what they re up to as well    named by yagami  not present  same scene  tsubaki s earlier bonfire lecture  pp 267 274  is the template for the plan yagami now pitches  the first year student body s coordination channel is recorded here as contextual fact only","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v3-p322-1\"><h3><span class=\"ttl\">Tsubaki named at the walkie-talkie debrief<\/span><span class=\"meta\">Y2V3 · p.322–329<\/span><\/h3><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Tsubaki-san and the others had been more informed than I anticipated. It was a surprise for me too.” — named by Yagami; not present; POV switch to Kushida.<span class=\"pg\">p.322<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “If you don’t willingly cooperate starting now, you might end up paying dearly later.” — Tsubaki&#x27;s earlier line retold in his account; not present; same scene.<span class=\"pg\">p.324<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “There’s a chance Tsubaki-san is conspiring something too. She might try and pull something at the same time as us, so I’ll be poking around to try and find out what they’re up to as well.” — named by Yagami; not present; same scene.<span class=\"pg\">p.329<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Tsubaki&#x27;s earlier bonfire lecture (pp.267–274) is the template for the plan Yagami now pitches; the first-year student body&#x27;s coordination channel is recorded here as contextual fact only.<span class=\"pg\">p.306–329<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v3-p267-1\">← Before: Tsubaki: the minds behind the bonfire<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v4-p121-1","v":"y2v4","y":2,"o":19,"k":"","w":"tsubaki-sakurako","q":"tsubaki sakurako tsubaki mentioned in passing  i don t know  but tsubaki was the main person i spoke to on the walkie talkie    nanase names her as the coordinator   i agree with you  because i had the impression that class c was more focused on utomiya  but utomiya and housen don t get along  and when it comes to arguing  they quickly get into quarrels  so tsubaki may have been deliberately chosen to act as an intermediary    nanase","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v4-p121-1\"><h3><span class=\"ttl\">Tsubaki mentioned in passing<\/span><span class=\"meta\">Y2V4 · p.121<\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “I don&#x27;t know, but Tsubaki was the main person I spoke to on the walkie-talkie.” — Nanase names her as the coordinator.<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “I agree with you, because I had the impression that Class C was more focused on Utomiya. But Utomiya and Housen don&#x27;t get along, and when it comes to arguing, they quickly get into quarrels, so Tsubaki may have been deliberately chosen to act as an intermediary.” — Nanase.<span class=\"pg\">p.121<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v4-p126-1\">→ After: Ch.5: The deal with Hōsen<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v4-p126-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"nanase-tsubasa housen-kazuomi utomiya-riku yagami-takuya tsubaki-sakurako","q":"tsubaki sakurako ch 5  the deal with hosen on day nine  tsubaki calls hosen on the walkie talkie to pitch a rescue plan for the sinking first year groups and an attack on ayanokoji  satoru like tsubaki stays calm  she intends to sacrifice herself if necessary   it s   because we need you to save us    tsubaki   are you saying you don t trust utomiya    utomiya   no  only with housen kun  it is a known fact that the two of you are on bad terms  and i am not willing to let the negotiations break out of unnecessary emotion    tsubaki   you already know that  right  four of the last ten groups are freshmen  also  the second group is first year d class  if the special exams end like this  the damage done to us freshmen and to housen kun s class will be great     one thing before answering  you re sure nanase is on our side  right     just so you know in a class d full of garbage  i am someone who could be useful    nanase   yes  so don t worry  but it s the right thing to do  i m going to bail out the last four current groups  as well as all the groups that are about to sink into the last five     you seem to take your time  although it is precious time    tsubaki   just for fun  do i send errand boy  katagiri  back half dead     don t get carried away  housen  if you put a hand on katagiri  you will see it with me    utomiya   that was a bit insistent    printed untagged  nanase or utomiya  not assigned   that s how i do it  now you know    hosen   i m sorry i made you wait   can we resume our discussion    tsubaki   you threatened him  right    tsubaki   it is difficult to be weak in a fight  because it is resolved before it begins  the same thing happens to you  you know  tsubaki      hosen   it s true that i can t win a fight if i go face to face  but not here    tsubaki   the head  the brain    tsubaki   there is a way to forcibly rescue groups from their situation  to do this  you will need as many helpers as possible  since it seems that those above are already using the same strategy  and we also need the help of the first year d class     i would love to help  but i have things to do  i m very busy   busy is   you are trying to expel ayanokouji senpai    tsubaki   that s what i mean  i don t care if the trash from my class disappears    but how do you plan to expel him  even on the morning of the eighth day  ayanokouji senpai continues to work alone  and yet it is not in the last 10 groups  the only conditions for being expelled from school are  according to the regulations  the only two options for this special exam  withdraw with the group or sink to the bottom of the score      tsubaki   it s true  some of them are already running out of food      utomiya   if the first five groups are defeated  it will be practically impossible to get ayanokouji senpai out of the school  right  you may think that rescuing the first years will also help ayanokouji senpai get expelled  right      tsubaki   so saving the first years  well  that doesn t sound so bad    let s hear how you do it    hosen   as i said before  we are going to stay together as one in our grade  like all the other students in the upper grades  we will absorb the sinking groups to the bottom and pick up where we left off with the groups we can afford  if need be  i could even use my hands to take homework from the group of sophomores and juniors sinking below      tsubaki   if it were so easy to assemble  we wouldn t have any problem  right  we have class a and class b  i don t think they will help class d and class c     i don t think we should worry about that  we have already decided to cooperate with each other  i m just waiting for housen s approval    tsubaki   it is not a bad idea  but there is no guarantee that you will win with it  after all  even if you use the same strategy  the scenario will be the same  the difference in experience  the result of losing the freshmen is unshakable     so is  at this rate  we may not be able to reduce the first year s sacrifice to zero      tsubaki   that s not what you were saying  didn t you think we were going to get all the first years out    tsubaki   i thought that the moment to make a move was when everyone started to get tired  we originally planned to do it between the eighth and the tenth day of the second half of the test  but something happened that we did not expect     and good  be specific about what you want me to do for you     the organizers of this test have made a proposal  they said they wouldn t mind bringing you down with an act of violence  housen kun  you are planning to forcibly defeat ayanokouji senpai  right     well  it s the only way   but it is difficult to keep ayanokoji senpai  who is always on the move in a solitary way  until now  housen kun has not been able to fulfill that opportunity  but it is different if there is a wide siege network  tsubaki mentioned that she would take on that role     i have been investigating how many of the first year students  including utomiya and housen  trust their ability to fight or use violence and have no resistance  if you surround him well  you can block his escape routes     do you want me to help you prepare the place   yes   would they cross such a dangerous bridge  i don t think they work for free  much less utomiya   of course  people who cooperate agree to do so for 500 000 points as a reward for success  i think it is a necessary expense to reduce housen kun s participation     wait  tsubaki  violence is forbidden as a general rule  would you act accordingly just to pay them 500 000     of course  you can t ask me to do this the first day  the second half of the test has been tough  both physically and mentally  student stress is considerable  we are all in a state of conflict between our desire to be comfortable and our desire to be radical  of course  i think they feel a strong resistance to taking the first blow  that is why i want to leave the leadership to you  housen kun     there are many people who want to ignore a red light in front of them  however  it is difficult to take the first step when there are other people s eyes  but if a person starts to cross  the situation changes     at that moment  it is either fight or lose both  i will take responsibility for expelling him as the brain that gave instructions to the first graders     i don t regret this school  so i feel like i can quit right away  i ve made sure all the guys in my group have private points and half price cards   people who can self destruct are scary  i have changed my mind     originally  when the special test was disclosed  i was the one who suggested that ayanokouji senpai be kicked out  you just went along with me  didn t you  utomiya kun     i see  so it is not a coincidence     if we follow you  no one will be expelled from our first year  can you guarantee it    hosen   i promise  and if something happens  i ll take the blame     did you take the recording correctly  is it not safe to have my testimony     and that  when are you going to do it     i can t tell you yet  i cannot easily divulge that information     that s what walkie talkies are for   that s what i mean    tsubaki   i ll get in touch when the time comes  thank you    tsubaki  she walks hosen through the whole plan  the four sunken first year groups  the absorb the sinking strategy  the 500 000 point bribe  the walkie talkie relay  the recording she has him make   she volunteers as ringleader and organizer  she stays composed  she expects to quit the school regardless  recruits him as the violent muscle  he only pretends to follow  her class 1 c partner  she reveals to him only what she must  fellow plotter  his  insurance  tablets  she clocks nanase as  useful  nanase is secretly ayanokoji s ally","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v4-p126-1\"><h3><span class=\"ttl\">Ch.5: The deal with Hōsen<\/span><span class=\"meta\">Y2V4 · p.126–139<\/span><\/h3><p class=\"setup\">On day nine, Tsubaki calls Hōsen on the walkie-talkie to pitch a rescue plan for the sinking first-year groups and an attack on Ayanokōji; Satoru-like Tsubaki stays calm; she intends to sacrifice herself if necessary.<\/p><p class=\"with\">with <a href=\"nanase-tsubasa.html\">Nanase Tsubasa<\/a> · <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"utomiya-riku.html\">Utomiya Riku<\/a> · <a href=\"yagami-takuya.html\">Yagami Takuya<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“It&#x27;s ...... because we need you to save us.” — Tsubaki.<span class=\"pg\">p.130<\/span><\/li><li class=\"q spoken\">“Are you saying you don&#x27;t trust Utomiya?” — Utomiya.<span class=\"pg\">p.131<\/span><\/li><li class=\"q spoken\">“No, only with Housen-kun. It is a known fact that the two of you are on bad terms, and I am not willing to let the negotiations break out of unnecessary emotion.” — Tsubaki.<span class=\"pg\">p.131<\/span><\/li><\/ul><details class=\"more\"><summary>59 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “You already know that, right? Four of the last ten groups are freshmen. Also, the second group is first-year D class. If the special exams end like this, the damage done to us freshmen and to Housen-kun&#x27;s class will be great. ”<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “One thing before answering. You&#x27;re sure Nanase is on our side, right? ”<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Just so you know in a class D full of garbage, I am someone who could be useful.” — Nanase.<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes. So don&#x27;t worry, but it&#x27;s the right thing to do. I&#x27;m going to bail out the last four current groups, as well as all the groups that are about to sink into the last five. ”<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You seem to take your time, although it is precious time.” — Tsubaki.<span class=\"pg\">p.132<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Just for fun, do I send errand boy ‘Katagiri’ back half dead? ”<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don&#x27;t get carried away, Housen. If you put a hand on Katagiri, you will see it with me.” — Utomiya.<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That was a bit insistent.” — printed untagged; Nanase or Utomiya; not assigned.<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s how I do it. Now you know”. — Hōsen.<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m sorry I made you wait .. Can we resume our discussion?” — Tsubaki.<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You threatened him, right?” — Tsubaki.<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It is difficult to be weak in a fight, because it is resolved before it begins. The same thing happens to you, you know? Tsubaki. ” — Hōsen.<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s true that I can&#x27;t win a fight if I go face to face. But not here.” — Tsubaki.<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The head, the brain.” — Tsubaki.<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There is a way to forcibly rescue groups from their situation. To do this, you will need as many helpers as possible. Since it seems that those above are already using the same strategy, and we also need the help of the first year D-class. ”<span class=\"pg\">p.134<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I would love to help, but I have things to do. I&#x27;m very busy.”<span class=\"pg\">p.134<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Busy is ...... you are trying to expel Ayanokouji-senpai?” — Tsubaki.<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s what I mean. I don&#x27;t care if the trash from my class disappears ”<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But how do you plan to expel him? Even on the morning of the eighth day, Ayanokouji-senpai continues to work alone. And yet it is not in the last 10 groups. The only conditions for being expelled from school are, according to the regulations, the only two options for this special exam: withdraw with the group or sink to the bottom of the score. ” — Tsubaki.<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s true. Some of them are already running out of food. ” — Utomiya.<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If the first five groups are defeated, it will be practically impossible to get Ayanokouji-senpai out of the school, right? You may think that rescuing the first years will also help Ayanokouji-senpai get expelled, right? ” — Tsubaki.<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So saving the first years. Well, that doesn&#x27;t sound so bad. ...... Let&#x27;s hear how you do it.” — Hōsen.<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “As I said before, we are going to stay together as one in our grade, like all the other students in the upper grades. We will absorb the sinking groups to the bottom and pick up where we left off with the groups we can afford. If need be, I could even use my hands to take homework from the group of sophomores and juniors sinking below. ” — Tsubaki.<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If it were so easy to assemble, we wouldn&#x27;t have any problem, right? We have Class A and Class B. I don&#x27;t think they will help Class D and Class C. ”<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t think we should worry about that. We have already decided to cooperate with each other. I&#x27;m just waiting for Housen&#x27;s approval” — Tsubaki.<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It is not a bad idea, but there is no guarantee that you will win with it. After all, even if you use the same strategy, the scenario will be the same. The difference in experience, the result of losing the freshmen is unshakable. ”<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So is. At this rate, we may not be able to reduce the first year&#x27;s sacrifice to zero. ” — Tsubaki.<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s not what you were saying. Didn&#x27;t you think we were going to get all the first years out?” — Tsubaki.<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I thought that the moment to make a move was when everyone started to get tired. We originally planned to do it between the eighth and the tenth day of the second half of the test, but something happened that we did not expect. ”<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “And good? Be specific about what you want me to do for you. ”<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The organizers of this test have made a proposal. They said they wouldn&#x27;t mind bringing you down with an act of violence. Housen-kun, you are planning to forcibly defeat Ayanokouji-senpai, right? ”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, it&#x27;s the only way.”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But it is difficult to keep Ayanokoji-senpai, who is always on the move in a solitary way. Until now, Housen-kun has not been able to fulfill that opportunity. But it is different if there is a wide siege network. Tsubaki mentioned that she would take on that role. ”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have been investigating how many of the first-year students, including Utomiya and Housen, trust their ability to fight or use violence and have no resistance. If you surround him well, you can block his escape routes. ”<span class=\"pg\">p.138<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you want me to help you prepare the place?”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes.”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Would they cross such a dangerous bridge? I don&#x27;t think they work for free, much less Utomiya”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Of course. People who cooperate agree to do so for 500,000 points as a reward for success. I think it is a necessary expense to reduce Housen-kun&#x27;s participation. ”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Wait, Tsubaki, Violence is forbidden as a general rule, would you act accordingly just to pay them 500,000? ”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Of course, you can&#x27;t ask me to do this the first day. The second half of the test has been tough, both physically and mentally. Student stress is considerable. We are all in a state of conflict between our desire to be comfortable and our desire to be radical. Of course, I think they feel a strong resistance to taking the first blow. That is why I want to leave the leadership to you, Housen-kun. ”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There are many people who want to ignore a red light in front of them. However, it is difficult to take the first step when there are other people&#x27;s eyes. But if a person starts to cross, the situation changes. ”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “At that moment, it is either fight or lose both. I will take responsibility for expelling him as the brain that gave instructions to the first graders... ”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t regret this school. So I feel like I can quit right away. I&#x27;ve made sure all the guys in my group have private points and half-price cards...”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “People who can self-destruct are scary. I have changed my mind. ”<span class=\"pg\">p.138<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Originally, when the special test was disclosed. I was the one who suggested that Ayanokouji-senpai be kicked out. You just went along with me, didn&#x27;t you, Utomiya-kun? ”<span class=\"pg\">p.138<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I see. So it is not a coincidence. ”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If we follow you, no one will be expelled from our first year. Can you guarantee it?” — Hōsen.<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I promise. And if something happens, I&#x27;ll take the blame. ”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Did you take the recording correctly? Is it not safe to have my testimony? ”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “And that? When are you going to do it? ”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I can&#x27;t tell you yet. I cannot easily divulge that information. ”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s what walkie-talkies are for.”<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s what I mean.” — Tsubaki.<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;ll get in touch when the time comes, thank you.” — Tsubaki.<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> She walks Hōsen through the whole plan: the four sunken first-year groups, the absorb-the-sinking strategy, the 500,000-point bribe, the walkie-talkie relay, the recording she has him make — she volunteers as ringleader and organizer; she stays composed; she expects to quit the school regardless.<span class=\"pg\">p.126–139<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> Recruits him as the violent muscle; he only pretends to follow.<span class=\"pg\">p.126–139<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> Her Class 1-C partner; she reveals to him only what she must.<span class=\"pg\">p.130–138<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yagami Takuya<\/b> Fellow plotter; his “insurance” tablets.<span class=\"pg\">p.141–147<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nanase Tsubasa<\/b> She clocks Nanase as “useful”; Nanase is secretly Ayanokōji&#x27;s ally.<span class=\"pg\">p.132<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v4-p121-1\">← Before: Tsubaki mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v4-p140-1\">→ After: Ch.5: The day-13 briefing; the insurance tablet<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v4-p140-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"yagami-takuya utomiya-riku tsubaki-sakurako","q":"tsubaki sakurako ch 5  the day 13 briefing  the insurance tablet the morning of day thirteen  utomiya finds her staring at the sky  yagami arrives with an  insurance  tablet from the same box as ayanokoji s   offered for free in exchange for her success   what are you thinking  tsubaki    utomiya   i was doing a final review in my head  what do you want   no  i just wanted to talk to you before the operation took place  it may be the last conversation with tsubaki so far     why didn t you use a walkie talkie to communicate with me    utomiya   you can t know what they really think if you don t talk to them face to face  you already heard my exchange with housen so you know exactly what i mean     i guess so  i didn t even know what he was thinking  but i don t trust him at all     utomiya turned his face away  looking unhappy at the fact that she had been pointed out that way    narration   utomiya kun is the only one i can trust among the first year students  i wanted to ask you directly about the plan and for you to say what you thought    how s the preparation going    utomiya   do you want to see the screenshot i took of one when i ran the gps search earlier    tsubaki   the arrangement is perfect  just as tsubaki planned    utomiya   well  we have carefully prepared up to this point  the land is on our side     tsubaki san  can we talk   i have something i need you to hear   sorry  but wait  there is something i have to talk to yagami first    utomiya   what happens    yagami   yesterday you suddenly disappeared  and where were you    utomiya   sorry  my watch broke and i had to run back to the starting point   a malfunction  it is the second time    utomiya   it is outrageous to be suspected of conspiring just because your watch malfunctions  utomiya kun also had a clock failure a few days ago  right  doesn t that mean that you re also a suspect     hey you two  could you please not get in trouble at a time like this  after all  we are friends  right      tsubaki   as for me  i don t want to do anything irregular  but let me tell you something   from now on  tsubaki san is going to corner ayanokouji senpai while repeatedly using gps search to find out his position  but it is inevitable that she will consume a lot of points to do so  right     that s why we have a group of reserve tablets    tsubaki   but it is not very favorable that it is efficient  you know why   we do not know where the designated area of ayanokouji senpai is  so we cannot predict his movements    tsubaki   that s right  if you are able to read through ayanokouji senpai s movements if he went to a designated area  if he pursues a task or just escapes  what is the priority and what needs to be blocked  your efficiency will increase drastically       in my own way  i spent a lot of time researching to see if there was anything i could do to help  so  among the 12 squares  which squares does ayanokouji senpai belong to     you mean you know    tsubaki   yes  well  technically  it s not me  it s just this  tablet  that tells me   i borrowed it from a group of my friends from class b  first year  because the owner of this table is in the same square as ayanokouji senpai     i would appreciate it if you could lend me that tablet  considering the points that i am going to consume  i would like to refrain from wasting as much as possible  do you think it s ok   also if you do not accept this proposal  we will not be able to provide you with insurance   our first priority is to use tsubaki s strategy to pursue ayanokouji senpai and force him to retreat  however  that can end in failure for some reason  for example  if ayanokouji senpai works with a third party for the entire day  because you can t attack someone where there are other people s eyes     if something unexpected goes wrong  we switch to the method of letting them pass through the entire designated area to score points  and tomorrow  the last day  the 14th  we have three more movements  and we seal it     no  you can make them step on it up to 7 times  ayanokouji senpai s box passed a total of two times yesterday on the day 12  the third area being randomly designated d4 that went far  and then the fourth area designated d2  which they also did not step on  we have already confirmed that we have changed our focus to accept the challenge     let s say seven times  that s less than 28 points  an exaggerated score   ayanokouji senpai is still alone right now  we do not know how many points he has  but since he is alone  it will not be many  also  you can use gps search on our forays  if we get ahead of that and seal their assignments as well  there is more than enough chance that he will sink into the bottom five groups     if i manage to get ayanokouji senpai out with this insurance  what if i get 5 million points and tsubaki san and the others get 10 million points as their share  i m sure you will agree to share the remaining 5 million points with the group that failed     well  if you even have a tablet in the same box  there s no way he won t     what is that tablet    yagami   the tablet from ayanokouji senpai s box    tsubaki    what  when did you     tsubaki san you are beyond my imagination  you even came up with this insurance strategy       if so  i cannot accept the reward  i reject the 5 million points  then i ll be watching from a distance     thanks  it s honestly hard to do it when you re around people you don t trust  so i guess that helps    tsubaki   shouldn t he be there after all  i m sure i can go one on one with ayanokouji and win    utomiya   that s not good  utomiya kun is an indispensable member of the first year c class  also  there is the possibility that i will be judged in the same way when taking responsibility  leave ayanokouji senpai for the other children    tsubaki   once ayanokouji senpai s elimination is over  before the school finds out i m here  i ll defeat some independent 2nd and 3rd grade groups and let s go who i can target    tsubaki  at 7 00 am the test begins  she sends the five groups into the field  e6 group heads north  d4 group stays put  she keeps the plan tight  six gps scheduled groups plus the  insurance  tablets  she knows yagami is opportunistic  she plays along until it s too late to matter  yagami presses his own tablet  she lets him in on the box match  her only trusted first year  he is warned off a direct fight","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v4-p140-1\"><h3><span class=\"ttl\">Ch.5: The day-13 briefing; the insurance tablet<\/span><span class=\"meta\">Y2V4 · p.140–149<\/span><\/h3><p class=\"setup\">The morning of day thirteen; Utomiya finds her staring at the sky; Yagami arrives with an “insurance” tablet from the same box as Ayanokōji&#x27;s — offered for free in exchange for her success.<\/p><p class=\"with\">with <a href=\"yagami-takuya.html\">Yagami Takuya<\/a> · <a href=\"utomiya-riku.html\">Utomiya Riku<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“What are you thinking? Tsubaki” — Utomiya.<span class=\"pg\">p.140<\/span><\/li><li class=\"q spoken\">“&#x27;I was doing a final review in my head. What do you want?&quot;”<span class=\"pg\">p.140<\/span><\/li><li class=\"q spoken\">“No, I just wanted to talk to you before the operation took place. It may be the last conversation with Tsubaki so far. ”<span class=\"pg\">p.140<\/span><\/li><\/ul><details class=\"more\"><summary>50 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Why didn&#x27;t you use a walkie-talkie to communicate with me?” — Utomiya.<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You can&#x27;t know what they really think if you don&#x27;t talk to them face to face. You already heard my exchange with Housen so you know exactly what I mean. ”<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I guess so. I didn&#x27;t even know what he was thinking, but I don&#x27;t trust him at all. ”<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Utomiya turned his face away, looking unhappy at the fact that she had been pointed out that way.” — narration.<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Utomiya-kun is the only one I can trust among the first-year students. I wanted to ask you directly about the plan and for you to say what you thought ”<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “How&#x27;s the preparation going?” — Utomiya.<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you want to see the screenshot I took of one when I ran the GPS search earlier?” — Tsubaki.<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The arrangement is perfect, just as Tsubaki planned.” — Utomiya.<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, we have carefully prepared up to this point. The land is on our side. ”<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Tsubaki-san, can we talk?”<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have something I need you to hear.”<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sorry, but wait, there is something I have to talk to Yagami first.” — Utomiya.<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What happens?.” — Yagami.<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yesterday you suddenly disappeared, and where were you?” — Utomiya.<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sorry, my watch broke and I had to run back to the starting point”<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “A malfunction? It is the second time.” — Utomiya.<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It is outrageous to be suspected of conspiring just because your watch malfunctions. Utomiya-kun also had a clock failure a few days ago, right? Doesn&#x27;t that mean that you&#x27;re also a suspect? ”<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hey you two, could you please not get in trouble at a time like this? After all, we are friends, right? ” — Tsubaki.<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “As for me, I don&#x27;t want to do anything irregular, but let me tell you something.”<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “From now on, Tsubaki-san is going to corner Ayanokouji-senpai while repeatedly using GPS search to find out his position, but it is inevitable that she will consume a lot of points to do so, right? ”<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s why we have a group of reserve tablets.” — Tsubaki.<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But it is not very favorable that it is efficient. You know why?”<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We do not know where the designated area of Ayanokouji-senpai is, so we cannot predict his movements.” — Tsubaki.<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s right. If you are able to read through Ayanokouji-senpai&#x27;s movements if he went to a designated area, if he pursues a task or just escapes, what is the priority and what needs to be blocked, your efficiency will increase drastically. . ”<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In my own way, I spent a lot of time researching to see if there was anything I could do to help. So, among the 12 squares, which squares does Ayanokouji-senpai belong to? ”<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You mean you know?” — Tsubaki.<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes, well, technically, it&#x27;s not me, it&#x27;s just this &#x27;tablet&#x27; that tells me.”<span class=\"pg\">p.144<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I borrowed it from a group of my friends from class B, first year. Because the owner of this table is in the same square as Ayanokouji-senpai. ”<span class=\"pg\">p.144<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I would appreciate it if you could lend me that tablet. Considering the points that I am going to consume, I would like to refrain from wasting as much as possible. Do you think it&#x27;s OK?”<span class=\"pg\">p.144<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Also if you do not accept this proposal, we will not be able to provide you with insurance.”<span class=\"pg\">p.145<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “&#x27;Our first priority is to use Tsubaki&#x27;s strategy to pursue Ayanokouji-senpai and force him to retreat. However, that can end in failure for some reason. For example, if Ayanokouji-senpai works with a third party for the entire day. Because you can&#x27;t attack someone where there are other people&#x27;s eyes. ”<span class=\"pg\">p.145<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If something unexpected goes wrong, we switch to the method of letting them pass through the entire designated area to score points. And tomorrow, the last day, the 14th, we have three more movements, and we seal it. ”<span class=\"pg\">p.145<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, you can make them step on it up to 7 times. Ayanokouji-senpai&#x27;s box passed a total of two times yesterday on the day 12, the third area being randomly designated D4 that went far, and then the fourth area designated D2, which they also did not step on. We have already confirmed that we have changed our focus to accept the challenge. ”<span class=\"pg\">p.145<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Let&#x27;s say seven times, that&#x27;s less than 28 points, an exaggerated score.”<span class=\"pg\">p.145<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ayanokouji-senpai is still alone right now. We do not know how many points he has, but since he is alone, it will not be many. Also, you can use GPS search on our forays. If we get ahead of that and seal their assignments as well, there is more than enough chance that he will sink into the bottom five groups. ”<span class=\"pg\">p.145<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If I manage to get Ayanokouji-senpai out with this insurance, what if I get 5 million points and Tsubaki-san and the others get 10 million points as their share? I&#x27;m sure you will agree to share the remaining 5 million points with the group that failed. ”<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, if you even have a tablet in the same box, there&#x27;s no way he won&#x27;t. ”<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What is that tablet?” — Yagami.<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The tablet from Ayanokouji-senpai&#x27;s box.” — Tsubaki.<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “ What? When did you...... ”<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Tsubaki-san you are beyond my imagination. You even came up with this insurance strategy. ...... ”<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If so, I cannot accept the reward, I reject the 5 million points. Then I&#x27;ll be watching from a distance. ”<span class=\"pg\">p.147<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “&#x27;Thanks, it&#x27;s honestly hard to do it when you&#x27;re around people you don&#x27;t trust, so I guess that helps.”&#x27; — Tsubaki.<span class=\"pg\">p.147<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Shouldn&#x27;t he be there after all? I&#x27;m sure I can go one-on-one with Ayanokouji and win.” — Utomiya.<span class=\"pg\">p.148<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s not good. Utomiya-kun is an indispensable member of the first-year C-Class. Also, there is the possibility that I will be judged in the same way when taking responsibility. Leave Ayanokouji-senpai for the other children.” — Tsubaki.<span class=\"pg\">p.148<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Once Ayanokouji-senpai&#x27;s elimination is over, Before the school finds out I&#x27;m here, I&#x27;ll defeat some independent 2nd and 3rd grade groups and let&#x27;s go who I can target.” — Tsubaki.<span class=\"pg\">p.149<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> At 7:00 AM the test begins; she sends the five groups into the field; E6 group heads north; D4 group stays put.<span class=\"pg\">p.149<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> She keeps the plan tight: six GPS-scheduled groups plus the &quot;insurance&quot; tablets; she knows Yagami is opportunistic; she plays along until it&#x27;s too late to matter.<span class=\"pg\">p.140–149<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yagami Takuya<\/b> Yagami presses his own tablet; she lets him in on the box-match.<span class=\"pg\">p.141–147<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> Her only trusted first-year; he is warned off a direct fight.<span class=\"pg\">p.140–149<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v4-p126-1\">← Before: Ch.5: The deal with Hōsen<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v4-p151-1\">→ After: Ch.5: The siege fails; the unseen commander<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v4-p151-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"yagami-takuya ayanokouji-kiyotaka tsubaki-sakurako","q":"tsubaki sakurako ch 5  the siege fails  the unseen commander at 7 00 am she orders the first years to close on ayanokoji  he flees south  she tracks him with 10 minute gps updates  the five groups she sent are boxed in by second years  yagami reports five frozen groups   on the move  huh    ayanokoji s interior as his group runs  not her line   if you can keep up with the movements  you will find a way to win with no contact    tsubaki   don t let him go out   it s so depressing    tsubaki   what s wrong  tsubaki san   what s wrong  tsubaki san   three of the five first year groups we sent have stopped moving  the three groups that stopped moving had one thing in common  they were all in the same position crossing paths with the sophomores     it certainly seems like a second year student is sabotaging them  but if it is   who   will it be   so you are saying that it is not just one particular class  but the entire second year that is doing the movement   these five groups do not understand why they have been ordered to stop us    tsubaki   we just have to spend time attacking now  but second year students can t protect ayanokouji senpai all the time  right  there are special tests   i think we should consider suspending the operation   i don t know who is directing everything  but i am here to show you that visual information is not everything    tsubaki   perhaps your commander has noticed the five first year groups we moved last night    tsubaki   now there is no one who can interfere  now you can do whatever you want    i told you  i told you that the information you see is not all there is    the plan collapses under the second years  coordination  she realizes ayanokoji contacted them ahead of time  she changes the search to 5 minute intervals  she pivots to leave the two following groups to their own devices  her siege is broken by his counter move  he escapes without contact  he watches her panic  she silences him","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v4-p151-1\"><h3><span class=\"ttl\">Ch.5: The siege fails; the unseen commander<\/span><span class=\"meta\">Y2V4 · p.151–158<\/span><\/h3><p class=\"setup\">At 7:00 AM she orders the first-years to close on Ayanokōji; he flees south; she tracks him with 10-minute GPS updates; the five groups she sent are boxed in by second-years; Yagami reports five frozen groups.<\/p><p class=\"with\">with <a href=\"yagami-takuya.html\">Yagami Takuya<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“If you can keep up with the movements, you will find a way to win with no contact.” — Tsubaki.<span class=\"pg\">p.153<\/span><\/li><li class=\"q spoken\">“Don&#x27;t let him go out.”<span class=\"pg\">p.154<\/span><\/li><li class=\"q spoken\">“It&#x27;s so depressing.” — Tsubaki.<span class=\"pg\">p.154<\/span><\/li><\/ul><details class=\"more\"><summary>16 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> &quot;On the move, huh?&quot; — Ayanokōji&#x27;s interior as his group runs; not her line.<span class=\"pg\">p.152<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What&#x27;s wrong, Tsubaki-san?”<span class=\"pg\">p.154<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What&#x27;s wrong, Tsubaki-san?”<span class=\"pg\">p.155<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Three of the five first-year groups we sent have stopped moving. The three groups that stopped moving had one thing in common: they were all in the same position crossing paths with the sophomores. ”<span class=\"pg\">p.155<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It certainly seems like a second year student is sabotaging them, but if it is ...... who ... will it be.”<span class=\"pg\">p.155<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So you are saying that it is not just one particular class, but the entire second year that is doing the movement?”<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “These five groups do not understand why they have been ordered to stop us.” — Tsubaki.<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We just have to spend time attacking now, but second-year students can&#x27;t protect Ayanokouji-senpai all the time, right? There are special tests.”<span class=\"pg\">p.157<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I think we should consider suspending the operation.”<span class=\"pg\">p.157<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t know who is directing everything, but I am here to show you that visual information is not everything.” — Tsubaki.<span class=\"pg\">p.158<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Perhaps your commander has noticed the five first-year groups we moved last night.” — Tsubaki.<span class=\"pg\">p.158<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Now there is no one who can interfere. Now you can do whatever you want ”<span class=\"pg\">p.158<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I told you. I told you that the information you see is not all there is. ”<span class=\"pg\">p.158<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> The plan collapses under the second-years&#x27; coordination; she realizes Ayanokōji contacted them ahead of time; she changes the search to 5-minute intervals; she pivots to leave the two following groups to their own devices.<span class=\"pg\">p.151–158<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Her siege is broken by his counter-move; he escapes without contact.<span class=\"pg\">p.151–158<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yagami Takuya<\/b> He watches her panic; she silences him.<span class=\"pg\">p.154–158<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v4-p140-1\">← Before: Ch.5: The day-13 briefing; the insurance tablet<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v4-p159-1\">→ After: Tsubaki mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v4-p159-1","v":"y2v4","y":2,"o":19,"k":"","w":"tsubaki-sakurako","q":"tsubaki sakurako tsubaki mentioned in passing  tsubaki replied a bit dejected  and looked at the tablet again    narration   takuya yagami kun  riku utomiya kun  and sakurako tsubaki san  i wonder who my adversary is  or is it the three of them    sakayanagi","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v4-p159-1\"><h3><span class=\"ttl\">Tsubaki mentioned in passing<\/span><span class=\"meta\">Y2V4 · p.159–160<\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> “Tsubaki replied a bit dejected, and looked at the tablet again.” — narration.<span class=\"pg\">p.159<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “Takuya Yagami-kun? Riku Utomiya-kun? and Sakurako Tsubaki-san? I wonder who my adversary is. Or is it the three of them?” — Sakayanagi.<span class=\"pg\">p.160<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v4-p151-1\">← Before: Ch.5: The siege fails; the unseen commander<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v4-p165-1\">→ After: Ch.5: &quot;I caught the other group&quot;<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v4-p165-1","v":"y2v4","y":2,"o":19,"k":"spoken","w":"yagami-takuya utomiya-riku kitou-hayato tsubaki-sakurako","q":"tsubaki sakurako ch 5   i caught the other group  receiving the news of hosen s defeat  tsubaki mutters in interest  she sees utomiya is missing  her walkie talkie is taken by kitou after his fight with utomiya  she realizes her plan was a dead end   it didn t go very well  did it   even if you force yourself to flee  you can always make up an excuse later  like you got scared because you got tangled up with the grown ups  if you had consulted me before    so  you say this happened because i was negligent    tsubaki   it is not that my group has been caught  it is that i have caught the other group   rumor has it that he has the ability similar to housen kun s  it means that he didn t want to face the current group from the beginning    tsubaki   the only thing we should avoid is getting in the way of our efforts to eliminate ayanokouji senpai  and the only person capable of eliminating ayanokouji senpai  apart from utomiya kun  is housen kun     yagami   let me ask you one last question  if housen kun had not accepted this case  do you think this operation would not have been possible      tsubaki   hmm  not exactly  it is correct to say that we decided to carry out this operation because we were absolutely sure that housen kun would come on board  it seems that he was always willing to fight alone  still  if they didn t accept the case  i would just let utomiya kun go  either way  i made sure the atmosphere was perfect for one on one  now it only remains for the two to face each other  win or lose  and everything will be fine    tsubaki  she takes the failure with interest   the whole plan was a test  she expected the second years to stop housen  she reveals she never meant to confront ayanokoji directly  kitou s approach forces her to abandon the island  her second in command  she tolerates his halting loyalty  her one trusted partner  his walkie talkie is lost to kitou  he was sent to unmask her  utomiya drops the walkie talkie and kitou reads her voice  the plan dies","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v4-p165-1\"><h3><span class=\"ttl\">Ch.5: &quot;I caught the other group&quot;<\/span><span class=\"meta\">Y2V4 · p.165–167<\/span><\/h3><p class=\"setup\">Receiving the news of Hōsen&#x27;s defeat, Tsubaki mutters in interest; she sees Utomiya is missing; her walkie-talkie is taken by Kitou after his fight with Utomiya; she realizes her plan was a dead end.<\/p><p class=\"with\">with <a href=\"yagami-takuya.html\">Yagami Takuya<\/a> · <a href=\"utomiya-riku.html\">Utomiya Riku<\/a> · <a href=\"kitou-hayato.html\">Kitō Hayato<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Yagami Takuya<\/b> “It didn&#x27;t go very well, did it?”<span class=\"pg\">p.165<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Yagami Takuya<\/b> “Even if you force yourself to flee, you can always make up an excuse later, like you got scared because you got tangled up with the grown-ups. If you had consulted me before ”<span class=\"pg\">p.165<\/span><\/li><li class=\"q spoken\">“So, you say this happened because I was negligent?” — Tsubaki.<span class=\"pg\">p.165<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “It is not that my group has been caught, it is that I have caught the other group.”<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Rumor has it that he has the ability similar to Housen-kun&#x27;s. It means that he didn&#x27;t want to face the current group from the beginning.” — Tsubaki.<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The only thing we should avoid is getting in the way of our efforts to eliminate Ayanokouji-senpai. And the only person capable of eliminating Ayanokouji-Senpai, apart from Utomiya-kun, is Housen-kun ...” — Yagami.<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Let me ask you one last question. If Housen-kun had not accepted this case, do you think this operation would not have been possible? ” — Tsubaki.<span class=\"pg\">p.167<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hmm, not exactly. It is correct to say that we decided to carry out this operation because we were absolutely sure that Housen-kun would come on board. It seems that he was always willing to fight alone. Still, if they didn&#x27;t accept the case, I would just let Utomiya-kun go. Either way, I made sure the atmosphere was perfect for one-on-one. Now it only remains for the two to face each other, win or lose, and everything will be fine.” — Tsubaki.<span class=\"pg\">p.167<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> She takes the failure with interest — the whole plan was a test; she expected the second-years to stop Housen; she reveals she never meant to confront Ayanokōji directly; Kitou&#x27;s approach forces her to abandon the island.<span class=\"pg\">p.165–167<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yagami Takuya<\/b> Her second-in-command; she tolerates his halting loyalty.<span class=\"pg\">p.165–167<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> Her one trusted partner; his walkie-talkie is lost to Kitou.<span class=\"pg\">p.165–190<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kitō Hayato<\/b> He was sent to unmask her; Utomiya drops the walkie-talkie and Kitou reads her voice; the plan dies.<span class=\"pg\">p.184–189<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v4-p159-1\">← Before: Tsubaki mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v4_5-p254-1","v":"y2v4.5","y":2,"o":20,"k":"","w":"tsubaki-sakurako","q":"tsubaki sakurako tsubaki  the utomiya sakayanagi angle yagami  explaining how he created a common enemy   he was thinking that he would definitely stop it the next time  to team up with another class who originally wouldn t join hands with you  the quickest and easiest method was to create a common enemy  hosen  i got into the pockets of tsubaki and utomiya   a common enemy  hosen  yagami s account reaches beyond this volume s exam   tsubaki was drawn into his scheme  no on page presence  no lines  no direct action attributed beyond yagami s summary","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v4_5-p254-1\"><h3><span class=\"ttl\">Tsubaki: the Utomiya–Sakayanagi angle<\/span><span class=\"meta\">Y2V4.5 · p.254<\/span><\/h3><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> Yagami, explaining how he created a common enemy: &quot;…He was thinking that he would definitely stop it the next time. To team up with another class who originally wouldn&#x27;t join hands with you, the quickest and easiest method was to create a common enemy, Hōsen. I got into the pockets of Tsubaki and Utomiya…&quot;; &quot;a common enemy, Hōsen.&quot;<span class=\"pg\">p.254–255<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Yagami&#x27;s account reaches beyond this volume&#x27;s exam — Tsubaki was drawn into his scheme; no on-page presence; no lines; no direct action attributed beyond Yagami&#x27;s summary.<span class=\"pg\">p.254<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-tsubaki-sakurako-y2v7-p191-1","v":"y2v7","y":2,"o":23,"k":"","w":"utomiya-riku ayanokouji-kiyotaka tsubaki-sakurako","q":"tsubaki sakurako tsubaki sakurako s white room play  2   after the festival ends  utomiya waits outside the school with tsubaki  ak receives a phone call from an unknown number at the classroom  the voice sounds familiar   tsubaki sakurako  a student in first year class c   hello    ayanokoji answers his phone   are you still in school  i d like to talk to you for a minute if you d like    the caller  the voice sounds familiar   are you alone now    ayanokoji   unfortunately not    the caller   then why don t we meet up    the caller   where are you    ayanokoji   i just left the front door  you re still on campus  right    the caller   give me five minutes    ayanokoji   okay    the caller  after a short call  he told horikita   i m sorry  but i m going to have to step out for a bit i ll be back in about 10 or 20 minutes  then we ll continue our conversation    he returned to the classroom to finish the conversation  horikita   okay  i ll wait here    she agrees to wait   2    is tsubaki alone at the meeting place    he thought so for a moment  but it seemed that utomiya was talking to someone a little farther away  he was only looking at them   is there something you re having trouble communicating over the phone    tsubaki asks ayanokoji  who was holding the phone   well  the first year students are in a bit of a mess right now  there was an unexpected expulsion at the school festival    tsubaki   expelled  that s a very disturbing story    ayanokoji  someone else was involved in this school expulsion fiasco  that was tsubaki sakurako  who was in front of him then   i m satisfied with the result  which is more than i imagined ayanokoji senpai    tsubaki   tsubaki made a circle with her finger as if to say   you passed    the narration   it seems you ve successfully extracted information from sato senpai and drove yagami kun out of school  i am very grateful    tsubaki  sato was apparently approached by tsubaki near the women s restroom at keyaki mall  there  she flashed some bait that would turn things around for her  including a turnaround between his relationship with kei  which tickled her curiosity  she intensified the threats gradually over days because sato would eventually come to consult someone  and that would be him  the goal was not to cage sato  but to wait for her to ask him for help  ayanokoji to tsubaki   it seems you called sato to your room and made cheap threats  but it wasn t a serious attempt to manipulate her into ruining our relationship  it was because you wanted to push her to act  or deal with the threat of kei s relationship  by indirectly letting her know that we were getting close  tsubaki listened silently  staring at him without denial  ayanokoji   then  you most likely told sato that it was yagami who was behind the threats  not you  tsubaki played dumb   i don t know what that means  what a surprise   as soon as you saw that sato wouldn t accept your invitation  you contacted her again as if to follow up and made similar comments and provoked her  when you saw that sato didn t seem to have consulted anyone  you gradually intensified your threats and hounded her  this was due to the fact that she would eventually come to consult someone  and that would be me    ayanokoji s read of the three week squeeze   yagami kun is a bad guy  isn t he    tsubaki   you don t need cheap theatrics  yagami had nothing to do with this  he s not involved    ayanokoji   you don t think it was actually yagami kun s order    tsubaki  the only people who know about karuizawa s past are those who are connected with the white room  others can t easily imitate him  tsubaki   then isn t it the other way around  you found out that i was trying to frame yagami kun  didn t you  and yet you did nothing against me and even expelled yagami kun  who might be innocent  isn t that contradictory  there was no indication that ayanokoji senpai was looking into it in detail  ayanokoji   ah  i didn t investigate tsubaki or yagami  no need for that  tsubaki   what do you mean  ayanokoji   i m sorry  but i don t feel like talking any more    he was convinced that he had said enough  it wasn t even tsubaki who was manipulating everything  furthermore  the person lurking in the background was the one who painted this picture   utomiya kun  can you come here for a minute    tsubaki beckoned to utomiya  who was on the phone  and instructed him to hand his cell phone to ayanokoji   go ahead    wary  utomiya handed the phone to him while it was still connected  the voice of the man he spoke to last year on the phone and in front of his room   yagami had some of tsubaki s and utomiya s classmates expelled  that s why those two worked together with me  the man on the phone continued   you left him alone because you knew you could take him down at any time if you moved directly on him  but as a result  there were expulsions from the first year  it wouldn t have happened if it hadn t been for his nuisance  ayanokoji   i don t deny it  the man on the phone   the only way to avoid further unnecessary sacrifices was to have him expelled  but even if you knew that  it isn t easy to defeat yagami  i know he is no ordinary high school student  ayanokoji   that s why you wanted to use me    he made this decision because he understood the white room student s purpose and obsession  the man on the phone   eventually  you ll get in touch with someone close to me  and when that happens  there will be expulsions  right  the phone man s line continues from p 196   that s right  but to drive yagami into a corner and expel him all at once  closes the previous page and  that was a little out of the calculations  did you not take into account the possibility that yagami was unrelated  is printed on p 197   two verbatim fragments split at the page turn  kept as printed  continuation kept in this file as separate rows rather than as one spliced quotation  the man on the phone   it was up to yagami s choice whether or not he wanted to be expelled  it wasn t me who decided whether it was black or white  he was playing with fire here and there  just like he expelled a student from 1st year c  he contacted kushida kikyo  pretending to be her former junior  and he used the information he was given to control and manipulate her  he provoked unrelated students on a deserted island by inflicting serious injuries to them  he also checked the contents of a love letter for another person  thinking it was a trap  i don t know why horikita and ibuki were there  but i think it was also because he was playing with fire   so it was all connected    the man on the phone   that guy didn t realize he was strangling himself with cotton wool    the man on the phone   surely if yagami hadn t done anything  he wouldn t have been expelled at this stage    the man on the phone  ayanokoji   i agree  the man on the phone   the only reason he was expelled was because yagami admitted to himself that he was black  he merely set up the stage for a test  if he was completely white  there would ve been no fuss in the first place  he only went to the student council room because he knew him and because he was smart  the man on the phone   you seem to be as good as the rumors say you are  the man on the phone   by the way  just to confirm  remember what you told me before  you told me that if i didn t get rid of the people who were in my way  i wouldn t expect peace and quiet to return  that was a bluff  wasn t it  you wanted to create a sense of urgency that if i didn t take care of the problem soon  it would become even more difficult  in order to make him move  he had made a move to get yagami expelled from the school from that stage  the man on the phone   ayanokoji sensei was right  you were right to choose this school  ayanokoji   what do you mean  the man on the phone   it s just as you believe  i m going to enjoy my school life  and as long as we don t bump into each other during the first and second years squabbles  i ll let our relationship end here  he said what he wanted to say and the call was unilaterally hung up  a sneak peek at the cell phone screen revealed that the call was deliberately blocked  this was done because they didn t want utomiya to realize from their address or phone number that they were registered to an address  tsubaki   have you figured it out  ayanokoji   yeah  ayanokoji   don t quit just because you ve defeated your enemy  tsubaki  tsubaki   i know  to be honest  i wasn t attached to this school at first  but that s changed a bit  this school is surprisingly fun  looking at the exchange just now  it was clear that there were a lot of mixed feelings other than simply taking revenge on an enemy  tsubaki   so  we re leaving  utomiya  forcing himself to pull out the honorific   senpai    returned to the dormitory with tsubaki  ayanokoji   i should get back to class too   there was an unexpected expulsion at the school festival    the school festival expelled someone  the person in front of him is tsubaki sakurako   i m satisfied with the result  which is more than i imagined ayanokoji senpai  utomiya is with tsubaki at the meeting  he hands his phone over   senpai  she works with him against yagami  she reports the expulsion  she leaves the school","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v7-p191-1\"><h3><span class=\"ttl\">Tsubaki Sakurako&#x27;s White Room play<\/span><span class=\"meta\">Y2V7 · p.191–199<\/span><\/h3><p class=\"setup\">§2 — after the festival ends; Utomiya waits outside the school with Tsubaki; AK receives a phone call from an unknown number at the classroom; the voice sounds familiar — Tsubaki Sakurako, a student in first-year Class C.<\/p><p class=\"with\">with <a href=\"utomiya-riku.html\">Utomiya Riku<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>65 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “Hello?” — Ayanokōji answers his phone.<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Are you still in school? I&#x27;d like to talk to you for a minute if you&#x27;d like.” — the caller; the voice sounds familiar.<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Are you alone now?” — Ayanokōji.<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Unfortunately not.” — the caller.<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Then why don&#x27;t we meet up?” — the caller.<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Where are you?” — Ayanokōji.<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “I just left the front door. You&#x27;re still on campus, right?” — the caller.<span class=\"pg\">p.191–192<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Give me five minutes.” — Ayanokōji.<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Okay.” — the caller.<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> After a short call, he told Horikita: “I&#x27;m sorry, but I&#x27;m going to have to step out for a bit…I&#x27;ll be back in about 10 or 20 minutes. Then we&#x27;ll continue our conversation.” — he returned to the classroom to finish the conversation.<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Horikita: “Okay, I&#x27;ll wait here.” — she agrees to wait.<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> §2 — “Is Tsubaki alone at the meeting place?” — he thought so for a moment, but it seemed that Utomiya was talking to someone a little farther away; he was only looking at them.<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Is there something you&#x27;re having trouble communicating over the phone?” — Tsubaki asks Ayanokōji, who was holding the phone.<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Well, the first-year students are in a bit of a mess right now. There was an unexpected expulsion at the school festival.” — Tsubaki.<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Expelled? That&#x27;s a very disturbing story.” — Ayanokōji.<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Someone else was involved in this school expulsion fiasco; that was Tsubaki Sakurako, who was in front of him then; “I&#x27;m satisfied with the result, which is more than I imagined…Ayanokōji-senpai.” — Tsubaki.<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Tsubaki made a circle with her finger as if to say, ‘you passed.’” — the narration; “It seems you&#x27;ve successfully extracted information from Satō-senpai and drove Yagami-kun out of school. I am very grateful.” — Tsubaki.<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Satō was apparently approached by Tsubaki near the women&#x27;s restroom at Keyaki Mall; there, she flashed some bait that would turn things around for her, including a turnaround between his relationship with Kei, which tickled her curiosity; she intensified the threats gradually over days because Satō would eventually come to consult someone, and that would be him; the goal was not to cage Satō, but to wait for her to ask him for help.<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ayanokōji to Tsubaki: “It seems you called Satō to your room and made cheap threats, but it wasn&#x27;t a serious attempt to manipulate her into ruining our relationship. It was because you wanted to push her to act, or deal with the threat of Kei&#x27;s relationship, by indirectly letting her know that we were getting close.”<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Tsubaki listened silently, staring at him without denial.<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ayanokōji: “Then, you most likely told Satō that it was Yagami who was behind the threats, not you.”<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Tsubaki played dumb: “I don&#x27;t know what that means. What a surprise.”<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “As soon as you saw that Satō wouldn&#x27;t accept your invitation, you contacted her again as if to follow up and made similar comments and provoked her. When you saw that Satō didn&#x27;t seem to have consulted anyone, you gradually intensified your threats and hounded her. This was due to the fact that she would eventually come to consult someone, and that would be me.” — Ayanokōji&#x27;s read of the three-week squeeze.<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Yagami-kun is a bad guy, isn&#x27;t he?” — Tsubaki.<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “You don&#x27;t need cheap theatrics. Yagami had nothing to do with this. He&#x27;s not involved.” — Ayanokōji.<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “You don&#x27;t think it was actually Yagami-kun&#x27;s order?” — Tsubaki.<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The only people who know about Karuizawa&#x27;s past are those who are connected with the White Room; others can&#x27;t easily imitate him.<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Tsubaki: “Then isn&#x27;t it the other way around, you found out that I was trying to frame Yagami-kun, didn&#x27;t you? And yet you did nothing against me and even expelled Yagami-kun, who might be innocent. Isn&#x27;t that contradictory? There was no indication that Ayanokōji-senpai was looking into it in detail.”<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ayanokōji: “Ah. I didn&#x27;t investigate Tsubaki or Yagami. No need for that.”<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Tsubaki: “What do you mean?”<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ayanokōji: “I&#x27;m sorry, but I don&#x27;t feel like talking any more.” — he was convinced that he had said enough; it wasn&#x27;t even Tsubaki who was manipulating everything; furthermore, the person lurking in the background was the one who painted this picture.<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Utomiya-kun, can you come here for a minute?” — Tsubaki beckoned to Utomiya, who was on the phone, and instructed him to hand his cell phone to Ayanokōji.<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Go ahead...” — Wary, Utomiya handed the phone to him while it was still connected.<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The voice of the man he spoke to last year on the phone and in front of his room: “Yagami had some of Tsubaki&#x27;s and Utomiya&#x27;s classmates expelled. That&#x27;s why those two worked together with me.”<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The man on the phone continued: “You left him alone because you knew you could take him down at any time if you moved directly on him. But as a result, there were expulsions from the first year. It wouldn&#x27;t have happened if it hadn&#x27;t been for his nuisance.”<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ayanokōji: “I don&#x27;t deny it.”<span class=\"pg\">p.196<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The man on the phone: “The only way to avoid further unnecessary sacrifices was to have him expelled. But even if you knew that, it isn&#x27;t easy to defeat Yagami. I know he is no ordinary high school student.”<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ayanokōji: “That&#x27;s why you wanted to use me.” — he made this decision because he understood the white room student&#x27;s purpose and obsession.<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The man on the phone: “Eventually, you&#x27;ll get in touch with someone close to me. And when that happens, there will be expulsions, right?”<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The phone man&#x27;s line continues from p.196: “That&#x27;s right. But to drive Yagami into a corner and expel him all at once?” closes the previous page and “That was a little out of the calculations. Did you not take into account the possibility that Yagami was unrelated?” is printed on p.197 — two verbatim fragments split at the page turn; kept as printed. Continuation kept in this file as separate rows rather than as one spliced quotation.<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The man on the phone: “It was up to Yagami&#x27;s choice whether or not he wanted to be expelled. It wasn&#x27;t me who decided whether it was black or white. He was playing with fire here and there, just like he expelled a student from 1st year C. He contacted Kushida Kikyo, pretending to be her former junior, and he used the information he was given to control and manipulate her. He provoked unrelated students on a deserted island by inflicting serious injuries to them. He also checked the contents of a love letter for another person, thinking it was a trap. I don&#x27;t know why Horikita and Ibuki were there, but I think it was also because he was playing with fire.”<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “So it was all connected.” — the man on the phone.<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “That guy didn&#x27;t realize he was strangling himself with cotton wool.” — the man on the phone.<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Surely if Yagami hadn&#x27;t done anything, he wouldn&#x27;t have been expelled at this stage.” — the man on the phone.<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ayanokōji: “I agree.”<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The man on the phone: “The only reason he was expelled was because Yagami admitted to himself that he was black.”<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> He merely set up the stage for a test; if he was completely white, there would&#x27;ve been no fuss in the first place; he only went to the student council room because he knew him and because he was smart.<span class=\"pg\">p.197<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The man on the phone: “You seem to be as good as the rumors say you are.”<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The man on the phone: “By the way, just to confirm, remember what you told me before? You told me that if I didn&#x27;t get rid of the people who were in my way, I wouldn&#x27;t expect peace and quiet to return. That was a bluff, wasn&#x27;t it? You wanted to create a sense of urgency that if I didn&#x27;t take care of the problem soon, it would become even more difficult.”<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> In order to make him move, he had made a move to get Yagami expelled from the school from that stage.<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The man on the phone: “Ayanokōji-sensei was right, you were right to choose this school.”<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ayanokōji: “What do you mean?”<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The man on the phone: “It&#x27;s just as you believe, I&#x27;m going to enjoy my school life, and as long as we don&#x27;t bump into each other during the first and second years squabbles, I&#x27;ll let our relationship end here.”<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> He said what he wanted to say and the call was unilaterally hung up; a sneak peek at the cell phone screen revealed that the call was deliberately blocked; this was done because they didn&#x27;t want Utomiya to realize from their address or phone number that they were registered to an address.<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Tsubaki: “Have you figured it out?”<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ayanokōji: “Yeah.”<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ayanokōji: “Don&#x27;t quit just because you&#x27;ve defeated your enemy, Tsubaki.”<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Tsubaki: “I know. To be honest, I wasn&#x27;t attached to this school at first, but that&#x27;s changed a bit. This school is surprisingly fun.”<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Looking at the exchange just now, it was clear that there were a lot of mixed feelings other than simply taking revenge on an enemy.<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Tsubaki: “So, we&#x27;re leaving.”<span class=\"pg\">p.199<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Utomiya, forcing himself to pull out the honorific: “Senpai.” — returned to the dormitory with Tsubaki.<span class=\"pg\">p.199<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ayanokōji: “I should get back to class too.”<span class=\"pg\">p.199<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> “There was an unexpected expulsion at the school festival.” — the school festival expelled someone; the person in front of him is Tsubaki Sakurako; “I&#x27;m satisfied with the result, which is more than I imagined…Ayanokōji-senpai.”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> Utomiya is with Tsubaki at the meeting; he hands his phone over; “Senpai.”<span class=\"pg\">p.191–199<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She works with him against Yagami; she reports the expulsion; she leaves the school.<span class=\"pg\">p.191–199<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-tsubaki-sakurako-y2v11-p46-1","v":"y2v11","y":2,"o":30,"k":"","w":"tsubaki-sakurako","q":"tsubaki sakurako ch 2  group 20 s first year class c at the inn  kiyotaka reads the group 20 roster  named as a first year class c member of group 20  tsubaki sakurako  shintoku taro  kiyotaka hardly knows the first years apart from tsubaki","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v11-p46-1\"><h3><span class=\"ttl\">Ch.2: Group 20&#x27;s first-year Class C<\/span><span class=\"meta\">Y2V11 · p.46<\/span><\/h3><p class=\"setup\">At the inn, Kiyotaka reads the Group 20 roster.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> Named as a first-year Class C member of Group 20: Tsubaki Sakurako, Shintoku Taro.<span class=\"pg\">p.46<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Kiyotaka hardly knows the first-years apart from Tsubaki.<span class=\"pg\">p.46<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v11-p137-1\">→ After: Ch.5: Surprisingly enthusiastic<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v11-p137-1","v":"y2v11","y":2,"o":30,"k":"","w":"tsubaki-sakurako","q":"tsubaki sakurako ch 5  surprisingly enthusiastic the girls  shared room  the first years get drawn into the card game   it seemed that the other first year students  tsubaki included  were surprisingly enthusiastic    unattributed narration  she is expected to be shy  she is not  named in the room s enthusiasm  not separately quoted on these pages","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v11-p137-1\"><h3><span class=\"ttl\">Ch.5: Surprisingly enthusiastic<\/span><span class=\"meta\">Y2V11 · p.137–140<\/span><\/h3><p class=\"setup\">The girls&#x27; shared room; the first-years get drawn into the card game.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “it seemed that the other first-year students, Tsubaki included, were surprisingly enthusiastic.” — unattributed narration; she is expected to be shy; she is not.<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Named in the room&#x27;s enthusiasm; not separately quoted on these pages.<span class=\"pg\">p.137<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v11-p46-1\">← Before: Ch.2: Group 20&#x27;s first-year Class C<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v11-p142-1\">→ After: Ch.5: The cute one<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v11-p142-1","v":"y2v11","y":2,"o":30,"k":"","w":"tsubaki-sakurako","q":"tsubaki sakurako ch 5  the cute one on the way to the rooms  the first year boys buzz about girls  rooms  tsubaki makes an impression   and wasn t tsubaki san cute    untagged first year  tsubaki is a first year of their group  the boys gawk","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v11-p142-1\"><h3><span class=\"ttl\">Ch.5: The cute one<\/span><span class=\"meta\">Y2V11 · p.142<\/span><\/h3><p class=\"setup\">On the way to the rooms; the first-year boys buzz about girls&#x27; rooms; Tsubaki makes an impression.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “And wasn&#x27;t Tsubaki-san cute?” — untagged first-year; Tsubaki is a first-year of their group; the boys gawk.<span class=\"pg\">p.142<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v11-p137-1\">← Before: Ch.5: Surprisingly enthusiastic<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v11-p152-1\">→ After: Ch.6: The shogi five<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v11-p152-1","v":"y2v11","y":2,"o":30,"k":"","w":"tsubaki-sakurako","q":"tsubaki sakurako ch 6  the shogi five the shogi lineup  she is named in it   the participants kiryuin chose were me  morishita  hashimoto  hiyori  and tsubaki    she is picked for the shogi match  she is in the room  named in narration  not present in the shogi scene","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v11-p152-1\"><h3><span class=\"ttl\">Ch.6: The shogi five<\/span><span class=\"meta\">Y2V11 · p.152<\/span><\/h3><p class=\"setup\">The shogi lineup; she is named in it.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “The participants Kiryūin chose were me, Morishita, Hashimoto, Hiyori, and Tsubaki.” — she is picked for the shogi match; she is in the room.<span class=\"pg\">p.152<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Named in narration; not present in the shogi scene.<span class=\"pg\">p.152<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v11-p142-1\">← Before: Ch.5: The cute one<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v11-p182-1\">→ After: Ch.8: The walk in the cold<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v11-p182-1","v":"y2v11","y":2,"o":30,"k":"spoken","w":"ayanokouji-kiyotaka hashimoto-masayoshi tsubaki-sakurako","q":"tsubaki sakurako ch 8  the walk in the cold sunday  fourth day  the camp ends today  she spots him in the dim lobby  they walk outside into the cold  the rematch with amasawa is set for 7 o clock  she heard from hashimoto senpai that he gets up early  she doesn t change her attitude toward anyone  her smile  if any  is rare   it s still quite early in the morning after all  isn t it   for the past two days  i heard from hashimoto senpai that you ve been getting up early in the morning   so  you came looking for me   not so much looking for you  but i just thought i d check if you were here   but if you were here  that would change things quite a bit   i don t think there s any reason for you to come see me anymore  the special exam given only to first year students has been canceled   i wasn t interested in the prize money from the start  but i m disappointed  i m lamenting the loss of the right to expel you in a dignified manner   that s dangerous talk  i don t remember you ever resenting me   don t you think there are more things you don t realize  people unknowingly incur resentment  you know   i can t tell if you re joking or serious   someone might come here  so why don t we take a walk   it s still dark outside   i thought it would be snowing quite a bit in the mountains of tochigi  but it s not as much as i thought   february has a drastic temperature difference  maybe it s because we ve had a few warm days recently   do you like snow  senpai   i don t particularly like or dislike it  i just think i enjoy the scenery when it snows  do you like snow  tsubaki   i guess i do  at least more than you  senpai   can you look at this   being in this school feels like being cut off from the outside world  doesn t it  who do you want to see first when you graduate next year  senpai   you ask strange questions   probably just my family   family  anyone else   not really  i don t have any close friends  so that s about it   i see  then  can i ask you one more strange question   imagine if you had a brother  and you didn t know about his existence because your parents hid it from you for years  but one day  you were told he was actually family  would you be able to love him as a family member  of course  assuming there is a genuine blood connection   that s a difficult question   i see  i think i would probably feel the same way as you  but  if i knew that the other person had special circumstances and a sad past  i would want to grow closer  i would like to know more about my sister  who i had been separated from   i might not feel anything  of course  i think it would greatly depend on the other person s personality and situation  her hypothetical   a hidden sibling kept secret for years  the way she frames it  my sister  who i had been separated from  strongly suggests personal experience  the brother sister switch is a deliberate evasion   i am confused  ayanokoji senpai  from this school    the sentence is intentionally vague and fragmented  she stops mid sentence when horikita  ibuki and kushida appear   we ve been interrupted  let s talk again later  she tests him with the sibling hypothetical  her real subject is never named on these pages  she heard from him that he rises early  she knows more than she lets on","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v11-p182-1\"><h3><span class=\"ttl\">Ch.8: The walk in the cold<\/span><span class=\"meta\">Y2V11 · p.182–185<\/span><\/h3><p class=\"setup\">Sunday, fourth day; the camp ends today; she spots him in the dim lobby; they walk outside into the cold; the rematch with Amasawa is set for 7 o&#x27;clock.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“It&#x27;s still quite early in the morning after all, isn&#x27;t it?”<span class=\"pg\">p.182<\/span><\/li><li class=\"q spoken\">“For the past two days, I heard from Hashimoto-senpai that you&#x27;ve been getting up early in the morning.”<span class=\"pg\">p.182<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “So, you came looking for me?”<span class=\"pg\">p.182<\/span><\/li><\/ul><details class=\"more\"><summary>31 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> She heard from Hashimoto-senpai that he gets up early; she doesn&#x27;t change her attitude toward anyone; her smile, if any, is rare.<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Not so much looking for you, but I just thought I&#x27;d check if you were here.”<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But if you were here, that would change things quite a bit.”<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t think there&#x27;s any reason for you to come see me anymore. The special exam given only to first-year students has been canceled.”<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I wasn&#x27;t interested in the prize money from the start, but I&#x27;m disappointed. I&#x27;m lamenting the loss of the right to expel you in a dignified manner.”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s dangerous talk. I don&#x27;t remember you ever resenting me.”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don&#x27;t you think there are more things you don&#x27;t realize? People unknowingly incur resentment, you know?”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I can&#x27;t tell if you&#x27;re joking or serious.”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Someone might come here, so why don&#x27;t we take a walk?”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s still dark outside.”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I thought it would be snowing quite a bit in the mountains of Tochigi, but it&#x27;s not as much as I thought.”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “February has a drastic temperature difference. Maybe it&#x27;s because we&#x27;ve had a few warm days recently.”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you like snow, Senpai?”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t particularly like or dislike it. I just think I enjoy the scenery when it snows. Do you like snow, Tsubaki?”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “...I guess I do. At least more than you, Senpai.”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Can you look at this?”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Being in this school feels like being cut off from the outside world, doesn&#x27;t it? Who do you want to see first when you graduate next year, Senpai?”<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You ask strange questions.”<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Probably just my family.”<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Family... Anyone else?”<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Not really. I don&#x27;t have any close friends, so that&#x27;s about it.”<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I see... Then, can I ask you one more strange question?”<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Imagine if you had a brother, and you didn&#x27;t know about his existence because your parents hid it from you for years. But one day, you were told he was actually family, would you be able to love him as a family member? Of course, assuming there is a genuine blood connection.”<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s a difficult question.”<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I see. I think I would probably feel the same way as you. But, if I knew that the other person had special circumstances and a sad past, I would want to grow closer. I would like to know more about my sister, who I had been separated from.”<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I might not feel anything. Of course, I think it would greatly depend on the other person&#x27;s personality and situation.”<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Her hypothetical — a hidden sibling kept secret for years; the way she frames it (“my sister, who I had been separated from”) strongly suggests personal experience; the brother-sister switch is a deliberate evasion.<span class=\"pg\">p.184–185<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “I am confused. Ayanokōji-senpai, from this school—” — the sentence is intentionally vague and fragmented; she stops mid-sentence when Horikita, Ibuki and Kushida appear.<span class=\"pg\">p.185<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We&#x27;ve been interrupted... Let&#x27;s talk again later.”<span class=\"pg\">p.185<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She tests him with the sibling hypothetical; her real subject is never named on these pages.<span class=\"pg\">p.182–185<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> She heard from him that he rises early; she knows more than she lets on.<span class=\"pg\">p.182–183<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-tsubaki-sakurako-y2v11-p152-1\">← Before: Ch.6: The shogi five<\/button><\/div><\/article>"},{"i":"sc-tsubaki-sakurako-y2v12-p12-1","v":"y2v12","y":2,"o":31,"k":"","w":"tsubaki-sakurako","q":"tsubaki sakurako tsubaki sakurako mentioned in passing named in this volume  passing mention  locator pages  p 28  not line by line verified  substring false positives possible  not a scene presence  passing mention only","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y2v12-p12-1\"><h3><span class=\"ttl\">tsubaki-sakurako mentioned in passing<\/span><span class=\"meta\">Y2V12 · p.12-228<\/span><\/h3><p class=\"setup\">Named in this volume.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention (locator pages: p.28; not line-by-line verified; substring false positives possible). Not a scene presence.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.12<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-tsubaki-sakurako-y3v2-p257-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"utomiya-riku housen-kazuomi nanase-tsubasa amasawa-ichika yagami-takuya ayanokouji-kiyotaka tsubaki-sakurako","q":"tsubaki sakurako  the six first year students  the plot against ayanokoji tsubaki and utomiya watch second year ayanokoji from a cafe  tsubaki asks if utomiya wants to move up to class a   tsubaki  do you want to move up to class a    utomiya  not really   it s housen and nanase   his actual fighting ability is unknown  but i can t imagine him losing to someone at housen s level   i think i ve become a little interested in getting to know you  utomiya kun    tsubaki  stop it  i don t pry into anyone s business  and i don t want anyone prying into mine    utomiya  either way  we re enemies    yagami hosen and nanase  first year class d  pass ayanokoji with only a polite nod from nanase  utomiya notices a bandage on ayanokoji s left hand and suspects a clash with hosen  utomiya rates ayanokoji far above hosen    everyone around him is weak    and dismisses hosen s rampages as because of weak opponents  amasawa  first year class a  teases the two about dating and leaves a blown kiss  she  takahashi and ishigami know of the special exam in class a  yagami joins  drawn by the  whole other level  of private points  utomiya  tsubaki  hosen  nanase  yagami and amasawa all target ayanokoji   a  baffling exam  targeting a specific individual  from this gathering the story connects to the upcoming uninhabited island special exam  tsubaki s cafe companion  both lack interest in class a special privileges  he is wary of prying  first year class d  utomiya suspects he may have clashed with ayanokoji and rates him low  first year class d  gave ayanokoji a polite nod  first year class a  teases tsubaki and utomiya and is involved in the first year special exam  first year class b  joins the conversation  drawn by the private points  the target of all six first years  they watch him and the bandage on his hand","h":"<article class=\"card\" id=\"sc-tsubaki-sakurako-y3v2-p257-1\"><h3><span class=\"ttl\">&quot;The Six First-Year Students&quot;: the plot against Ayanokōji<\/span><span class=\"meta\">Y3V2 · p.257–260<\/span><\/h3><p class=\"setup\">Tsubaki and Utomiya watch second-year Ayanokōji from a cafe; Tsubaki asks if Utomiya wants to move up to Class A.<\/p><p class=\"with\">with <a href=\"utomiya-riku.html\">Utomiya Riku<\/a> · <a href=\"housen-kazuomi.html\">Hōsen Kazuomi<\/a> · <a href=\"nanase-tsubasa.html\">Nanase Tsubasa<\/a> · <a href=\"amasawa-ichika.html\">Amasawa Ichika<\/a> · <a href=\"yagami-takuya.html\">Yagami Takuya<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Tsubaki, do you want to move up to Class A?&quot; — Utomiya<span class=\"pg\">p.257<\/span><\/li><li class=\"q spoken\">&quot;Not really.&quot;<span class=\"pg\">p.257<\/span><\/li><li class=\"q spoken\">&quot;It&#x27;s Housen and Nanase.&quot;<span class=\"pg\">p.257<\/span><\/li><\/ul><details class=\"more\"><summary>14 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;His actual fighting ability is unknown, but I can&#x27;t imagine him losing to someone at Housen&#x27;s level.&quot;<span class=\"pg\">p.258<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I think I&#x27;ve become a little interested in getting to know you, Utomiya-kun.&quot; — Tsubaki<span class=\"pg\">p.258<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Stop it. I don&#x27;t pry into anyone&#x27;s business, and I don&#x27;t want anyone prying into mine.&quot; — Utomiya<span class=\"pg\">p.258<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Either way, we&#x27;re enemies.&quot; — Yagami<span class=\"pg\">p.259<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Hōsen and Nanase (first-year Class D) pass Ayanokōji with only a polite nod from Nanase; Utomiya notices a bandage on Ayanokōji&#x27;s left hand and suspects a clash with Hōsen.<span class=\"pg\">p.257<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Utomiya rates Ayanokōji far above Hōsen — &quot;everyone around him is weak&quot; — and dismisses Hōsen&#x27;s rampages as because of weak opponents.<span class=\"pg\">p.257–258<\/span><\/li><li><span class=\"mlabel\">Detail<\/span> Amasawa (first-year Class A) teases the two about dating and leaves a blown kiss; she, Takahashi and Ishigami know of the special exam in Class A. Yagami joins, drawn by the &quot;whole other level&quot; of Private Points.<span class=\"pg\">p.258–259<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Utomiya, Tsubaki, Hōsen, Nanase, Yagami and Amasawa all target Ayanokōji — a &quot;baffling exam&quot; targeting a specific individual; from this gathering the story connects to the upcoming uninhabited-island special exam.<span class=\"pg\">p.260<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> Tsubaki&#x27;s cafe companion; both lack interest in Class A/special privileges; he is wary of prying.<span class=\"pg\">p.257–260<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hōsen Kazuomi<\/b> First-year Class D; Utomiya suspects he may have clashed with Ayanokōji and rates him low.<span class=\"pg\">p.257–258<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nanase Tsubasa<\/b> First-year Class D; gave Ayanokōji a polite nod.<span class=\"pg\">p.257<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> First-year Class A; teases Tsubaki and Utomiya and is involved in the first-year special exam.<span class=\"pg\">p.258–259<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yagami Takuya<\/b> First-year Class B; joins the conversation, drawn by the Private Points.<span class=\"pg\">p.259–260<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> The target of all six first-years; they watch him and the bandage on his hand.<span class=\"pg\">p.257–260<\/span><\/li><\/ul><\/details><\/article>"}];
